def boundary_of_binary_tree(root: Optional[TreeNode]) -> list[int]:
    if root is None:
        return []

    def is_leaf(node):
        return node.left is None and node.right is None

    result = [root.val]
    if is_leaf(root):
        return result
    # Left boundary, top down, excluding leaves.
    node = root.left
    while node is not None and not is_leaf(node):
        result.append(node.val)
        node = node.left if node.left is not None else node.right
    # Leaves from left to right (root is not a leaf here).
    stack = [root]
    while stack:
        cur = stack.pop()
        if is_leaf(cur):
            result.append(cur.val)
            continue
        if cur.right is not None:
            stack.append(cur.right)
        if cur.left is not None:
            stack.append(cur.left)
    # Right boundary, collected top down, appended bottom up.
    right = []
    node = root.right
    while node is not None and not is_leaf(node):
        right.append(node.val)
        node = node.right if node.right is not None else node.left
    result.extend(reversed(right))
    return result

