class Vector2D:
    def __init__(self, vec: list[list[int]]):
        self.vec = vec
        self.row = 0   # index of the current inner list
        self.col = 0   # index inside that inner list

    def _advance(self) -> None:
        # Skip rows that are empty or fully consumed.
        while self.row < len(self.vec) and self.col == len(self.vec[self.row]):
            self.row += 1
            self.col = 0

    def next(self) -> int:
        self._advance()
        value = self.vec[self.row][self.col]
        self.col += 1
        return value

    def hasNext(self) -> bool:
        self._advance()
        return self.row < len(self.vec)

