def max_width_ramp(nums: list[int]) -> int:
    # Indices of prefix minima: strictly decreasing values, increasing indices.
    stack = []
    for i, value in enumerate(nums):
        if not stack or nums[stack[-1]] > value:
            stack.append(i)

    best = 0
    for j in range(len(nums) - 1, -1, -1):
        # Every candidate whose value fits under nums[j] is matched with the widest j.
        while stack and nums[stack[-1]] <= nums[j]:
            best = max(best, j - stack.pop())
        if not stack:
            break
    return best

def triangle_number(nums: list[int]) -> int:
    nums = sorted(nums)
    count = 0
    # Fix the largest side, then count valid pairs to its left with two pointers.
    for k in range(len(nums) - 1, 1, -1):
        longest = nums[k]
        i, j = 0, k - 1
        while i < j:
            if nums[i] + nums[j] > longest:
                count += j - i   # every index i..j-1 works with j
                j -= 1
            else:
                i += 1
    return count

