def longest_path(parent: list[int], s: str) -> int:
    n = len(parent)
    children = [[] for _ in range(n)]
    for child in range(1, n):
        children[parent[child]].append(child)

    # BFS order: parents before children.
    order = [0]
    for node in order:
        order.extend(children[node])

    down = [1] * n      # longest valid chain starting at node and going down
    best = 1
    for node in reversed(order):
        top1 = top2 = 0
        for child in children[node]:
            if s[child] == s[node]:
                continue
            length = down[child]
            if length > top1:
                top1, top2 = length, top1
            elif length > top2:
                top2 = length
        down[node] = 1 + top1
        best = max(best, 1 + top1 + top2)
    return best

