def path_sum(root: Optional[TreeNode], targetSum: int) -> list[list[int]]:
    result = []
    if root is None:
        return result
    path = []                                # values from the root to the current node
    stack = [(root, 0, targetSum)]           # (node, depth, sum still needed)
    while stack:
        node, depth, need = stack.pop()
