def search(nums: list[int], target: int) -> bool:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return True
        if nums[lo] == nums[mid] == nums[hi]:
            # Cannot tell which side is sorted; both ends are not the target.
            lo += 1
            hi -= 1
        elif nums[lo] <= nums[mid]:
