def sort_list(head: Optional[ListNode]) -> Optional[ListNode]:
    def split(node, size):
        """Cut the list after `size` nodes starting at node; return the remainder."""
        for _ in range(size - 1):
            if node is None:
                break
            node = node.next
        if node is None:
            return None
        rest = node.next
        node.next = None
        return rest

    def merge(a, b, tail):
        """Merge sorted lists a and b after `tail`; return the new tail."""
        while a and b:
            if a.val <= b.val:
                tail.next, a = a, a.next
            else:
                tail.next, b = b, b.next
            tail = tail.next
        tail.next = a or b
        while tail.next:
            tail = tail.next
        return tail

    length = 0
    node = head
    while node:
        length += 1
        node = node.next

    dummy = ListNode(0, head)
    size = 1
    while size < length:
        tail = dummy
        cur = dummy.next
        while cur:
            left = cur
            right = split(left, size)
            cur = split(right, size)
            tail = merge(left, right, tail)
        size *= 2
    return dummy.next

