def find_min_step(board: str, hand: str) -> int:
    def collapse(row: str) -> str:
        """Remove runs of 3 or more equal balls until none remain."""
        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(row):
                j = i
                while j < len(row) and row[j] == row[i]:
                    j += 1
                if j - i >= 3:
                    row = row[:i] + row[j:]
                    changed = True
                    break
                i = j
        return row

    start = (board, "".join(sorted(hand)))
    queue = deque([(board, start[1], 0)])
    seen = {start}
    while queue:
        row, balls, used = queue.popleft()
        for i in range(len(row) + 1):
            for j, ball in enumerate(balls):
                if j > 0 and balls[j - 1] == ball:
                    continue                     # same colour already tried here
                if i > 0 and row[i - 1] == ball:
                    continue                     # equivalent to inserting one slot earlier
                touches = i < len(row) and row[i] == ball
                splits = 0 < i < len(row) and row[i - 1] == row[i] != ball
                if not (touches or splits):
                    continue
                new_row = collapse(row[:i] + ball + row[i:])
                if not new_row:
                    return used + 1
                state = (new_row, balls[:j] + balls[j + 1:])
                if state not in seen:
                    seen.add(state)
                    queue.append((new_row, state[1], used + 1))
    return -1

def remove_invalid_parentheses(s: str) -> list[str]:
    # Minimum number of '(' and ')' to delete.
    extra_open = extra_close = 0
    for ch in s:
        if ch == "(":
            extra_open += 1
        elif ch == ")":
            if extra_open:
                extra_open -= 1
            else:
                extra_close += 1

    n = len(s)
    found = set()
    path = []

    def dfs(i: int, open_count: int, del_open: int, del_close: int, prev_kept: str) -> None:
        if del_open + del_close > n - i:
            return                                   # not enough characters left to delete
        if i == n:
            if open_count == 0:
                found.add("".join(path))
            return
        ch = s[i]
        if ch == "(" or ch == ")":
            budget = del_open if ch == "(" else del_close
            # Delete it, unless the same character was just kept (would duplicate).
            if budget and prev_kept != ch:
                if ch == "(":
                    dfs(i + 1, open_count, del_open - 1, del_close, "")
                else:
                    dfs(i + 1, open_count, del_open, del_close - 1, "")
            # Keep it.
            if ch == "(":
                path.append(ch)
                dfs(i + 1, open_count + 1, del_open, del_close, ch)
                path.pop()
            elif open_count:
                path.append(ch)
                dfs(i + 1, open_count - 1, del_open, del_close, ch)
                path.pop()
        else:
            path.append(ch)
            dfs(i + 1, open_count, del_open, del_close, "")
            path.pop()

    dfs(0, 0, extra_open, extra_close, "")
    return list(found)

