def closest_value(root: Optional[TreeNode], target: float) -> int:
    best = root.val
    node = root
    while node is not None:
        gap, best_gap = abs(node.val - target), abs(best - target)
        # Closer wins; on an exact tie keep the smaller value.
        if gap < best_gap or (gap == best_gap and node.val < best):
            best = node.val
        node = node.left if target < node.val else node.right
    return best

def network_delay_time(times: list[list[int]], n: int, k: int) -> int:
    graph = defaultdict(list)
    for u, v, w in times:
        graph[u].append((v, w))
    arrival = {}                 # node -> final earliest arrival time
    heap = [(0, k)]
    while heap:
        t, node = heapq.heappop(heap)
        if node in arrival:
            continue             # already finalized with a smaller time
        arrival[node] = t
        for nxt, w in graph[node]:
            if nxt not in arrival:
                heapq.heappush(heap, (t + w, nxt))
    return max(arrival.values()) if len(arrival) == n else -1

