def min_moves(nums: list[int]) -> int:
    # Raising n - 1 elements equals lowering one element, relative to the rest,
    # so every element must be lowered to the minimum.
    smallest = min(nums)
    return sum(nums) - smallest * len(nums)

def makesquare(matchsticks: list[int]) -> bool:
    total = sum(matchsticks)
    if len(matchsticks) < 4 or total % 4:
        return False
    side = total // 4
    sticks = sorted(matchsticks, reverse=True)   # big sticks first fail fast
    if sticks[0] > side:
        return False
    sides = [0, 0, 0, 0]

    def place(i: int) -> bool:
        if i == len(sticks):
            return True          # nothing overflowed and the totals sum to 4 * side
        tried = set()
        for s in range(4):
            if sides[s] in tried or sides[s] + sticks[i] > side:
                continue         # same fill as a side already tried, or overflow
            tried.add(sides[s])
            sides[s] += sticks[i]
            if place(i + 1):
                return True
            sides[s] -= sticks[i]
        return False

    return place(0)

def find_maximized_capital(k: int, w: int, profits: list[int], capital: list[int]) -> int:
    projects = sorted(zip(capital, profits))   # by required capital
    available = []                             # max heap of profits (negated)
    i, n = 0, len(projects)
    for _ in range(k):
        # Unlock every project the current capital can afford.
        while i < n and projects[i][0] <= w:
            heapq.heappush(available, -projects[i][1])
            i += 1
        if not available:
            break                              # nothing affordable remains
        w -= heapq.heappop(available)          # take the best profit
    return w

def shortest_palindrome(s: str) -> str:
    rev = s[::-1]
    combined = s + "#" + rev
    fail = [0] * len(combined)   # KMP prefix function
    for i in range(1, len(combined)):
        k = fail[i - 1]
        while k and combined[i] != combined[k]:
            k = fail[k - 1]
        if combined[i] == combined[k]:
            k += 1
        fail[i] = k
    p = fail[-1]                 # length of the longest palindromic prefix
    return rev[:len(s) - p] + s

class NumMatrix:
    def __init__(self, matrix: list[list[int]]):
        m, n = len(matrix), len(matrix[0])
        # pre[r][c] = sum of matrix[0..r-1][0..c-1]; row 0 and column 0 are padding.
        self.pre = [[0] * (n + 1) for _ in range(m + 1)]
        for r in range(m):
            above, row = self.pre[r], self.pre[r + 1]
            running = 0
            for c in range(n):
                running += matrix[r][c]
                row[c + 1] = above[c + 1] + running

    def sumRegion(self, row1: int, col1: int, row2: int, col2: int) -> int:
        p = self.pre
        # Inclusion and exclusion over four corner blocks.
        return p[row2 + 1][col2 + 1] - p[row1][col2 + 1] - p[row2 + 1][col1] + p[row1][col1]

