def find_unsorted_subarray(nums: list[int]) -> int:
    n = len(nums)
    end, running_max = -1, nums[0]
    for i in range(1, n):
        if nums[i] < running_max:
            end = i              # something bigger sits to the left
        else:
            running_max = nums[i]
    if end == -1:
        return 0                 # already sorted
    start, running_min = n, nums[-1]
    for i in range(n - 2, -1, -1):
        if nums[i] > running_min:
            start = i            # something smaller sits to the right
        else:
            running_min = nums[i]
    return end - start + 1

