class Leaderboard:
    def __init__(self):
        self.total = {}        # playerId -> current total
        self.ordered = []      # all current totals, ascending

    def _drop(self, value: int) -> None:
        self.ordered.pop(bisect.bisect_left(self.ordered, value))

    def addScore(self, playerId: int, score: int) -> None:
        old = self.total.get(playerId)
        if old is not None:
            self._drop(old)
            score += old
        self.total[playerId] = score
        bisect.insort(self.ordered, score)

    def top(self, K: int) -> int:
        return sum(self.ordered[-K:])   # the K largest totals

    def reset(self, playerId: int) -> None:
        old = self.total.pop(playerId, None)
        if old is not None:
            self._drop(old)

