def check(args, got, expected):
    a, b, k = args
    if not isinstance(got, (list, tuple)) or len(got) != k:
        return False
    count_a, count_b = Counter(a), Counter(b)
    used = Counter()
    sums = []
    for p in got:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            return False
        u, v = p
        if u not in count_a or v not in count_b:
            return False
        used[(u, v)] += 1
        # a value pair can appear at most as often as there are index pairs producing it
        if used[(u, v)] > count_a[u] * count_b[v]:
            return False
        sums.append(u + v)
    return sorted(sums) == sorted(u + v for u, v in expected)

