def visible_points(points: list[list[int]], angle: int, location: list[int]) -> int:
    px, py = location
    at_me = 0
    angles = []
    for x, y in points:
        if x == px and y == py:
            at_me += 1                       # visible from any direction
        else:
            angles.append(math.degrees(math.atan2(y - py, x - px)))
    angles.sort()
    angles += [a + 360.0 for a in angles]    # unroll the circle once
    best = left = 0
    for right in range(len(angles)):
        while angles[right] - angles[left] > angle + 1e-9:
            left += 1
        best = max(best, right - left + 1)
    return best + at_me

def repeated_substring_pattern(s: str) -> bool:
    n = len(s)
    border = [0] * n        # KMP prefix function
    for i in range(1, n):
        k = border[i - 1]
        while k and s[i] != s[k]:
            k = border[k - 1]
        if s[i] == s[k]:
            k += 1
        border[i] = k
    p = border[-1]          # longest proper prefix that is also a suffix
    return p > 0 and n % (n - p) == 0

